-- Display the original Steps 2 workbook by printed page and fixed diagram position.
-- Existing IDs remain stable so saved progress continues to work.
WITH positions AS (
  SELECT
    id,
    CAST(substr(id, 6, instr(substr(id, 6), '-') - 1) AS INTEGER) AS page_number,
    CAST(substr(json_extract(definition_json, '$.title'), instr(json_extract(definition_json, '$.title'), ', Puzzle ') + 9) AS INTEGER) AS page_position
  FROM puzzles
  WHERE collection_slug = 'steps-2-workbook'
)
UPDATE puzzles
SET definition_json = json_set(
  definition_json,
  '$.title', printf(
    'Puzzle %d.%d',
    (SELECT page_number FROM positions WHERE positions.id = puzzles.id),
    (SELECT page_position FROM positions WHERE positions.id = puzzles.id)
  ),
  '$.sourcePage', (SELECT page_number FROM positions WHERE positions.id = puzzles.id),
  '$.pagePosition', (SELECT page_position FROM positions WHERE positions.id = puzzles.id)
)
WHERE id IN (SELECT id FROM positions);

-- Chess Steps 2 Mix has no progress worth retaining, so replace its temporary
-- sequential IDs and discard the answer/example material from printed page 3.
DELETE FROM practice_attempts
WHERE puzzle_id IN (SELECT id FROM puzzles WHERE collection_slug = 'chess-steps-2-mix');
DELETE FROM puzzles WHERE collection_slug = 'chess-steps-2-mix';
DELETE FROM puzzle_sections WHERE collection_slug = 'chess-steps-2-mix';

  'chess-steps-2-mix',
  'workbook-puzzles',
  'Workbook Puzzles',
  'Mixed positions from the workbook.',
  'Pages 4–8',
  0
);

